import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { roundCents } from './money.js';

/**
 * Generate a report of overdue invoices.
 * @param {Array<{ status: string, number: string, customerId: string, dueDate: string, lines: Array, payments?: Array }>} invoices
 * @param {string} asOf - Cutoff date in YYYY-MM-DD format (inclusive)
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} - Overdue invoices sorted by daysOverdue descending
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => {
      const daysOverdue = daysBetween(inv.dueDate, asOf);
      const due = balanceDue(inv);
      return {
        number: inv.number || '',
        customerId: inv.customerId,
        dueDate: inv.dueDate,
        daysOverdue,
        due,
      };
    })
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Generate a VAT summary report.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} - VAT by rate, sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  for (const invoice of invoices) {
    // Only process invoices with these statuses
    if (invoice.status !== 'issued' && invoice.status !== 'partially_paid' && invoice.status !== 'paid') {
      continue;
    }

    for (const line of invoice.lines) {
      // Calculate taxable amount (line total after discount)
      const lineTotal = line.qty * line.unitPrice;
      const lineDiscount = line.discountPercent ? roundCents((lineTotal * line.discountPercent) / 100) : 0;
      const taxableAmount = roundCents(lineTotal - lineDiscount);

