  // Customer 1: 2 invoices
  for (let i = 0; i < 2; i++) {
    const inv = issueInvoice(createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-14',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).value, [`2025-000${i}`]).value;
    invoices.push(inv);
  }

  // Customer 2: 1 invoice
  const inv2 = issueInvoice(createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value, ['2025-0002']).value;
  invoices.push(inv2);

  // Customer 3: 1 invoice with payment
  let inv3 = issueInvoice(createInvoice({
    customerId: 'C-003',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value, ['2025-0003']).value;
  inv3 = recordPayment(inv3, { amount: 20000, date: '2025-03-01' }).value;
  invoices.push(inv3);

  const result = dashboard(invoices, '2025-03-01');

  // C-001 should be first (2 invoices)
  assert.equal(result.topCustomers[0].customerId, 'C-001');
  // C-002 or C-003 could be second/third
  assert.equal(result.topCustomers.length, 3);
});

test('dashboard: returns max 3 customers', () => {
  const invoices = [];

  // Create 5 customers with issued invoices
  for (let i = 1; i <= 5; i++) {
    const inv = issueInvoice(createInvoice({
      customerId: `C-${String(i).padStart(3, '0')}`,
      issueDate: '2025-02-14',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).value, [`2025-000${i}`]).value;
    invoices.push(inv);
  }

  const result = dashboard(invoices, '2025-03-01');

  assert.equal(result.topCustomers.length, 3);
});

test('dashboard: handles draft invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const result = dashboard([draft], '2025-03-01');

  assert.equal(result.counts.draft, 1);
  assert.equal(result.outstanding, 0);
  assert.equal(result.topCustomers.length, 0);
});

test('dashboard: excludes paid invoices from outstanding', () => {
  let issued = issueInvoice(createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value, []).value;

  // Record payment for full amount
  const paymentResult = recordPayment(issued, { amount: 100000, date: '2025-03-01' });
  let paid = paymentResult.value;

  // Record another payment to mark as fully paid
  const result = dashboard([paid], '2025-03-01');

  assert.equal(result.counts.paid, 1);
  assert.equal(result.outstanding, 0);
  assert.equal(result.topCustomers.length, 0);
});

test('dashboard: orders top customers by amount due descending', () => {
  const invoices = [];

  // Customer 1: 1 invoice with 10 qty (highest)
  const inv1 = issueInvoice(createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 9 }],
  }).value, ['2025-0001']).value;
  invoices.push(inv1);

  // Customer 2: 1 invoice with 5 qty (middle)
  const inv2 = issueInvoice(createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value, ['2025-0002']).value;
  invoices.push(inv2);

  // Customer 3: 1 invoice with 3 qty (lowest)
  const inv3 = issueInvoice(createInvoice({
    customerId: 'C-003',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  }).value, ['2025-0003']).value;
  invoices.push(inv3);

  const result = dashboard(invoices, '2025-03-01');

  assert.equal(result.topCustomers[0].customerId, 'C-001');
  assert.equal(result.topCustomers[1].customerId, 'C-002');
  assert.equal(result.topCustomers[2].customerId, 'C-003');
  assert(result.topCustomers[0].due >= result.topCustomers[1].due);
  assert(result.topCustomers[1].due >= result.topCustomers[2].due);
});

